/**
 * Render the WeChat data overview panel (space-capsule cockpit).
 * @param props - navigation, chat and moments deep-link callbacks.
 * @returns the overview element tree.
 */
export function OverviewPanel({ onNavigate, onOpenChat, onOpenMoments }: {
  onNavigate?: (tab: string) => void
  onOpenChat?: (username: string) => void
  onOpenMoments?: (username: string) => void
} = {}): React.JSX.Element {
  const [data, setData] = useState<OverviewSnapshot | null>(() => readCache(CACHE_BASE) as OverviewSnapshot | null)
  const [ins, setIns] = useState<OverviewInsights | null>(() => readCache(CACHE_INSIGHTS) as OverviewInsights | null)
  const [ledger, setLedger] = useState<LedgerSnapshot | null>(() => readCache(CACHE_LEDGER) as LedgerSnapshot | null)
  const [stor, setStor] = useState<StorageSnapshot | null>(() => readCache(CACHE_STOR) as StorageSnapshot | null)
  const [loading, setLoading] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [exporting, setExporting] = useState(false)
  const [notice, setNotice] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<number | null>(() => readCache(CACHE_TIME) as number | null)
  const [done, setDone] = useState(false)
  const doneTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const rootRef = useRef<HTMLDivElement | null>(null)
  const [exportOpen, setExportOpen] = useState(false)

  const load = async (): Promise<void> => {
    const hadData = data !== null
    if (hadData) setRefreshing(true)
    else setLoading(true)
    try {
      const [base, insw] = await Promise.all([
        apiGetOverview(),
        apiGetOverviewInsights(),
      ])
      setData(base)
      setIns(insw)
      writeCache(CACHE_BASE, base)
      writeCache(CACHE_INSIGHTS, insw)
      setError(null)
      const now = Date.now()
      setLastUpdated(now)
      writeCache(CACHE_TIME, now)
      if (hadData) {
        setDone(true)
        if (doneTimer.current) clearTimeout(doneTimer.current)
        doneTimer.current = setTimeout(() => { setDone(false) }, 1600)
      }
    } catch (e) {
      if (data === null) setError((e as Error).message)
      else setNotice('后台刷新失败，当前显示缓存数据：' + (e as Error).message)
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
    // 资金/存储等较重扩展数据在后台慢慢更新并持久化，不阻塞核心刷新。
    try {
      const [lg, st] = await Promise.all([
        apiGetLedger(),
        apiGetStorageStats(),
      ])
      setLedger(lg)
      setStor(st)
      writeCache(CACHE_LEDGER, lg)
      writeCache(CACHE_STOR, st)
    } catch {
      /* 保留已有缓存/数据 */
    }
  }

  useEffect(() => { void load() }, [])
  useWechatDataUpdated(() => { void load() })
  // 朋友圈活跃作者头像改为逐行懒加载：作者卡片进入可视区附近时才请求头像。

  const go = (tab: string): void => { onNavigate?.(tab) }
  const openChat = (username: string): void => { onOpenChat?.(username) }
  const openMoments = (username: string): void => { onOpenMoments?.(username) }
  const topBase = (ins?.relations.top[0]?.count ?? 1) || 1
  const extras = ins?.extras

  const exportAll = async (): Promise<void> => {
    setExporting(true)
    try {
      const r = await apiExportAllSessions()
      setNotice('已归档 ' + String(r.count) + ' 条消息 → ' + r.path)
      setTimeout(() => { setNotice(null) }, 6000)
    } catch (e) {
      setNotice('归档失败: ' + (e as Error).message)
    } finally {
      setExporting(false)
    }
  }
  const doExport = async (format: 'md' | 'json' | 'png' | 'jpg'): Promise<void> => {
    if (!data) return
    const now = new Date()
    const stamp = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}`
    if (format === 'json') {
      const payload = {
        exportedAt: now.toISOString(),
        updatedAt: lastUpdated ? new Date(lastUpdated).toISOString() : null,
        snapshot: data,
        insights: ins,
        ledger,
        storage: stor,
      }
      downloadText(`微信数据总览-${stamp}.json`, JSON.stringify(payload, null, 2), 'application/json')
    } else if (format === 'md') {
      downloadText(`微信数据总览报告-${stamp}.md`, buildOverviewReport(data, ins, ledger, stor, now, lastUpdated), 'text/markdown;charset=utf-8')
    } else {
      setExportOpen(false)
      await new Promise((r) => { setTimeout(r, 40) })
      const root = rootRef.current
      if (root) {
        try {
          await exportElementImage(root, format, `微信数据总览-${stamp}.${format}`)
        } catch (e) {
          setNotice('图片导出失败: ' + (e as Error).message)
          return
        }
      }
    }
    setNotice('已导出报告')
    setTimeout(() => { setNotice(null) }, 2500)
  }


  const ls = ledger?.summary
  const largeFiles = stor?.large_files?.slice(0, 4) ?? []
  const warnCount = ledger?.warnings.length ?? 0

  return (
    <div ref={rootRef} className={refreshing ? `${css.root} ${css.updating}` : css.root}>
      {refreshing && <div className={css.scanbar} />}
      {/* 机舱头部 */}
      <PanelHeader
        title="微信数据总览"
        desc={(
          <>
            太空舱 · 本机微信数据资产一屏纵览
            {refreshing && <><span className={css.spinner} /> 同步中…</>}
            {lastUpdated ? ` · 最后更新 ${fmtTime(lastUpdated)}` : ''}
          </>
        )}
        actions={(
          <>
            <button type="button" className={css.refresh} onClick={() => { void exportAll() }} disabled={exporting}>
              {exporting ? '归档中…' : '导出全部会话 ZIP'}
            </button>
            <button type="button" className={css.refresh} onClick={() => { void load() }} disabled={loading || refreshing}>
              {(loading || refreshing)
                ? <><span className={css.spinner} /> {loading ? '统计中…' : '更新中…'}</>
                : done ? '✓ 已更新' : '刷新'}
            </button>
            <div className={css.exportWrap}>
              <button type="button" className={css.refresh} onClick={() => { setExportOpen(v => !v) }} disabled={!data}>
                导出 ▾
              </button>
              {exportOpen && (
                <>
                  <div className={css.exportBackdrop} onClick={() => { setExportOpen(false) }} />
                  <div className={css.exportMenu}>
                    <button type="button" className={css.exportItem} onClick={() => { void doExport('md'); setExportOpen(false) }}>Markdown 报告</button>
                    <button type="button" className={css.exportItem} onClick={() => { void doExport('json'); setExportOpen(false) }}>JSON 数据</button>
                    <button type="button" className={css.exportItem} onClick={() => { void doExport('png'); setExportOpen(false) }}>PNG 图片</button>
                    <button type="button" className={css.exportItem} onClick={() => { void doExport('jpg'); setExportOpen(false) }}>JPG 图片</button>
                  </div>
                </>
              )}
            </div>
          </>
        )}
      />

      {notice && <div className={css.error}>{notice}</div>}
      {error && data === null && <div className={css.error}>{error}</div>}
      {error && data !== null && <div className={css.error}>后台刷新失败（正在展示缓存数据）</div>}
      {!error && data === null && <div className={css.loading}><span className={css.spinner} /> 正在统计微信数据…</div>}

      {!error && data !== null && (
        <>
          {/* Hero：核心统计 + 行动入口 并排 */}
          <div className={css.cols}>
            <div className={css.heroLeft}>
              <Card title="核心资产">
                <div className={css.heroStats}>
                  {CARDS.slice(0, 4).map((card) => {
                    const value = card.key === 'storage'
                      ? fmtBytes(data.storage.total_size)
                      : (data[card.key as keyof OverviewSnapshot] as number).toLocaleString()
                    const sub = card.key === 'storage' ? `${data.storage.total_count.toLocaleString()} 项` : undefined
                    const tone = card.key === 'moments' ? 'purple'
                      : card.key === 'official' ? 'blue'
                        : card.key === 'storage' ? 'green' : 'cyan'
                    return (
                      <StatCard
                        key={card.key}
                        icon={card.icon}
                        value={value}
                        label={card.label}
                        hint={sub}
                        tone={tone}
                        onClick={() => { go(card.tab) }}
                        title={`查看${card.label}`}
                      />
                    )
                  })}
                </div>
              </Card>
            </div>
            <div className={css.heroRight}>
              <Card title="行动入口">
                <div className={css.quickGrid}>
                  {QUICK_ACTIONS.map(a => (
                    <button key={a.tab} type="button" className={css.quickCard} onClick={() => { go(a.tab) }} title={a.desc}>
                      <span className={css.quickIcon}>{a.icon}</span>
                      <span className={css.quickBody}>
                        <span className={css.quickTitle}>{a.title}</span>
                        <span className={css.quickDesc}>{a.desc}</span>
                      </span>
                      <span className={css.quickArrow}>→</span>
                    </button>
                  ))}
                </div>
              </Card>
            </div>
          </div>

          {/* 世界板块：好友地区分布钻取地图（滚动到可视区附近才挂载加载） */}
          <Card title="世界板块 · 好友地区">
            <LazyMount placeholder={<div className={css.empty}>地图进入可视区后加载…</div>}>
              <Suspense fallback={<div className={css.empty}>地图资源加载中…</div>}>
                <WorldMapPanel />
              </Suspense>
            </LazyMount>
          </Card>

          {/* 双列：轨道趋势 + 消息热度日历 */}
          {extras && (
            <div className={css.cols}>
              <Card title="轨道趋势">
                <div className={css.trendGrid}>
                  <div className={css.trendCell}>
                    <span className={css.metricValue}>{extras.trends.messages7.toLocaleString()}</span>
                    <span className={css.metricLabel}>近 7 天消息</span>
                    <span className={deltaArrow(extras.trends.messages7Delta).cls}>{deltaArrow(extras.trends.messages7Delta).text}</span>
                  </div>
                  <div className={css.trendCell}>
                    <span className={css.metricValue}>{extras.trends.messages30.toLocaleString()}</span>
                    <span className={css.metricLabel}>近 30 天消息</span>
                    <span className={deltaArrow(extras.trends.messages30Delta).cls}>{deltaArrow(extras.trends.messages30Delta).text}</span>
                  </div>
                  <div className={css.trendCell}>
                    <span className={css.metricValue}>{extras.trends.activeContacts30.toLocaleString()}</span>
                    <span className={css.metricLabel}>近 30 天活跃好友</span>
                  </div>
                  <div className={css.trendCell}>
                    <span className={css.metricValue}>{extras.trends.activeGroups30.toLocaleString()}</span>
                    <span className={css.metricLabel}>近 30 天活跃群</span>
                  </div>
                  <div className={css.trendCell}>
                    <span className={css.metricValue}>{fmtBytes(extras.trends.storageBytes30)}</span>
                    <span className={css.metricLabel}>近 30 天新增媒体</span>
                  </div>
                </div>
              </Card>
              {extras.heatmap.length > 0 && (
                <Card title="消息热度 · 近 90 天">
                  <CalendarHeatmap data={extras.heatmap} />
                </Card>
              )}
            </div>
          )}

          {/* 双列：存储构成 + 撤回 */}
          <div className={kitCss.cardGrid}>
            <Card
              title={`存储构成 Top ${data.storage.categories.length}`}
              extra={(
                <button type="button" className={css.panelGo} onClick={() => { go('storage') }}>详情 →</button>
              )}
            >
              {data.storage.categories.length === 0 ? (
                <div className={css.empty}>暂无媒体资源记录</div>
              ) : (
                <div className={css.catList}>
                  {data.storage.categories.slice(0, 4).map(c => (
                    <div key={c.label} className={css.cat}>
                      <div className={css.catRow}>
                        <span className={css.catLabel}>{c.label}</span>
                        <span className={css.catMeta}>{c.count.toLocaleString()} 项 · {fmtBytes(c.size)}</span>
                      </div>
                      <div className={css.bar}>
                        <div className={css.barFill}
                          style={{ width: `${(c.size / Math.max(1, data.storage.categories[0]?.size ?? 1)) * 100}%` }} />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Card>

            <Card
              title="撤回消息痕迹"
              extra={(
                <button type="button" className={css.panelGo} onClick={() => { go('revoked') }}>详情 →</button>
              )}
            >
              <div className={css.revoke}>
                <span className={css.revokeValue}>{data.revoked.toLocaleString()}</span>
                <span className={css.revokeLabel}>条被撤回消息的元数据痕迹（发送者/时间/类型可查）</span>
                <p className={css.revokeNote}>微信 4.x 防撤回机制在本地保留的删除缓存，可用于回顾"谁撤回了什么"。</p>
              </div>
            </Card>
          </div>

          {/* 资金快照 + 清理建议 */}
          <div className={kitCss.cardGrid}>
            <Card
              title={`资金快照 · ${ledger?.month ?? ''}`}
              extra={(
                <button type="button" className={css.panelGo} onClick={() => { go('ledger') }}>详情 →</button>
              )}
            >
              {ls ? (
                <div className={css.metricGrid}>
                  <div className={css.metric}>
                    <span className={css.metricValue}>¥{ls.totalAmountIn.toFixed(2)}</span>
                    <span className={css.metricLabel}>收入</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>¥{ls.totalAmountOut.toFixed(2)}</span>
                    <span className={css.metricLabel}>支出</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ls.transfers.toLocaleString()}</span>
                    <span className={css.metricLabel}>转账次数</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ls.redpacketsSent + ls.redpacketsReceived}</span>
                    <span className={css.metricLabel}>红包收/发</span>
                  </div>
                </div>
              ) : (
                <div className={css.empty}>暂无资金记录</div>
              )}
            </Card>

            <Card
              title="存储清理建议"
              extra={(
                <button type="button" className={css.panelGo} onClick={() => { go('storage') }}>详情 →</button>
              )}
            >
              <div className={css.metricGrid}>
                <div className={css.metric}>
                  <span className={css.metricValue}>{fmtBytes(stor?.total_size ?? 0)}</span>
                  <span className={css.metricLabel}>媒体占用</span>
                </div>
                <div className={css.metric}>
                  <span className={css.metricValue}>{(stor?.total_count ?? 0).toLocaleString()}</span>
                  <span className={css.metricLabel}>媒体项</span>
                </div>
                <div className={css.metric}>
                  <span className={css.metricValue}>{largeFiles.length}</span>
                  <span className={css.metricLabel}>超大文件</span>
                </div>
              </div>
            </Card>
          </div>

          {/* 双列：交互画像 + 关系浓度 */}
          {ins && (
            <div className={css.cols}>
              <Card title="交互画像 · 基于消息时间与类型">
                <div className={css.metricGrid}>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.messages.total.toLocaleString()}</span>
                    <span className={css.metricLabel}>消息总数</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.time.activeDays}</span>
                    <span className={css.metricLabel}>活跃天数</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.time.spanDays}</span>
                    <span className={css.metricLabel}>时间跨度(天)</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.time.busyHour}:00</span>
                    <span className={css.metricLabel}>最忙时段 · {ins.time.busyCount.toLocaleString()} 条</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.time.deepNightPct}%</span>
                    <span className={css.metricLabel}>深夜(23-6点)占比</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.time.weekendPct}%</span>
                    <span className={css.metricLabel}>周末占比</span>
                  </div>
                </div>
                <div className={css.hourBars}>
                  {ins.time.hourDist.map((n, h) => {
                    const max = Math.max(1, ...ins.time.hourDist)
                    return (
                      <div key={h} className={css.hourCol} title={`${h}:00 · ${n} 条`}>
                        <div
                          className={css.hourFill}
                          style={{ height: `${Math.max(4, (n / max) * 100)}%` }}
                          data-hot={n === ins.time.busyCount || undefined}
                        />
                        <span className={css.hourLabel}>{h}</span>
                      </div>
                    )
                  })}
                </div>
              </Card>

              <Card title="关系浓度 · 好友活跃与对话 Top">
                <div className={css.metricGrid}>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.relations.total}</span>
                    <span className={css.metricLabel}>好友总数</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.relations.active}</span>
                    <span className={css.metricLabel}>有消息往来</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.relations.silent}</span>
                    <span className={css.metricLabel}>沉默好友(无消息)</span>
                  </div>
                  <div className={css.metric}>
                    <span className={css.metricValue}>{ins.relations.groupsWithMsg}</span>
                    <span className={css.metricLabel}>有消息的群</span>
                  </div>
                </div>
                {ins.relations.top.length > 0 && (
                  <div className={css.topList}>
                    {ins.relations.top.map((t, i) => (
                      <button key={t.username} type="button" className={css.topRow} onClick={() => { openChat(t.username) }}
                        title={`与「${t.name}」的对话`}>
                        <span className={css.topRank}>{i + 1}</span>
                        <span className={css.topName}>{t.name}</span>
                        <div className={css.topTrack}>
                          <div className={css.topFill} style={{ width: `${(t.count / topBase) * 100}%` }} />
                        </div>
                        <span className={css.topCount}>{t.count} 条</span>
                      </button>
                    ))}
                  </div>
                )}
              </Card>
            </div>
          )}

          {/* 双列：朋友圈活跃 Top 20 + (内容构成 + 风险 + 健康) */}
          <div className={css.cols}>
            {data.moments_authors.length > 0 && (
              <Card
                title="朋友圈活跃 Top 20"
                extra={(
                  <button type="button" className={css.panelGo} onClick={() => { go('moments') }}>详情 →</button>
                )}
              >
                <div className={css.authors}>
                  {data.moments_authors.map((a, i) => (
                    <button key={a.username} type="button" className={css.author} onClick={() => { openMoments(a.username) }}
                      title={`${a.name} 共发布 ${a.posts} 条`}>
                      <span className={css.authorRank}>{i + 1}</span>
                      <LazyMount placeholder={<span className={css.authorAvatarFallback}>{(a.name || '?').slice(0, 1)}</span>} rootMargin="300px 0px">
                        <AuthorAvatar author={a} />
                      </LazyMount>
                      <span className={css.authorName}>{a.name}</span>
                      <span className={css.authorPosts}>{a.posts} 条</span>
                    </button>
                  ))}
                </div>
              </Card>
            )}

            <div className={css.colStack}>
              {/* 内容构成与资产 */}
              {ins && (
                <Card title="内容构成与资产">
                  <div className={css.catList}>
                    {MSG_BUCKETS.map((x) => {
                      const n = ins.messages[x.key]
                      const max = Math.max(1, ins.messages.text)
                      return (
                        <div key={x.label} className={css.cat}>
                          <div className={css.catRow}>
                            <span className={css.catLabel}>{x.label}</span>
                            <span className={css.catMeta}>{n.toLocaleString()} 条</span>
                          </div>
                          <div className={css.bar}><div className={css.barFill} style={{ width: `${(n / max) * 100}%` }} /></div>
                        </div>
                      )
                    })}
                  </div>
                  <div className={css.catRow} style={{ marginTop: 10 }}>
                    <span className={css.catLabel}>资产</span>
                    <span className={css.catMeta}>
                      {`朋友圈 ${ins.moments.total}(图${ins.moments.images}/赞${ins.moments.likes}/评${ins.moments.comments})` +
                       ` · 收藏 ${ins.assets.favorites} · 表情 ${ins.assets.emoticons}` +
                       ` · 文件 ${ins.assets.files} (${fmtBytes(ins.assets.fileBytes)})`}
                    </span>
                  </div>
                </Card>
              )}

              {/* 风险提示 */}
              <Card
                title="风险与隐私提示"
                extra={(
                  <button type="button" className={css.panelGo} onClick={() => { go('privacytrust') }}>详情 →</button>
                )}
              >
                <div className={css.riskRow}>
                  <span className={css.riskItem}>撤回消息 <b>{data.revoked.toLocaleString()}</b> 条</span>
                  <span className={css.riskItem}>转账/红包异常 <b>{warnCount}</b> 条</span>
                  <span className={css.riskItem}>建议定期运行「隐私与信任」扫描</span>
                </div>
              </Card>

              {/* 数据健康 */}
              {ins && (
                <Card title="数据健康">
                  <div className={css.metricGrid}>
                    <div className={css.metric}>
                      <span className={css.metricValue}>{ins.health.dbFiles}</span>
                      <span className={css.metricLabel}>数据库文件</span>
                    </div>
                    <div className={css.metric}>
                      <span className={css.metricValue}>{fmtBytes(ins.health.dbBytes)}</span>
                      <span className={css.metricLabel}>解密数据体积</span>
                    </div>
                    <div className={css.metric}>
                      <span className={css.metricValue}>{ins.health.ok ? '✅' : '⚠️'}</span>
                      <span className={css.metricLabel}>数据可读性</span>
                    </div>
                    <div className={css.metric}>
                      <span className={css.metricValue}>{ins.time.lastActive || '—'}</span>
                      <span className={css.metricLabel}>最近活跃</span>
                    </div>
                    {extras && (
                      <div className={css.metric}>
                        <span className={css.metricValue}>{extras.freshness.walPending ? '⚠️' : '✅'}</span>
                        <span className={css.metricLabel}>WAL 待落库</span>
                      </div>
                    )}
                  </div>
                </Card>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  )
}
