/**
 * 微信问答面板 — 基于本机聊天记录检索 + DSH LLM 生成回答，引用可点击跳转。
 * 检索在本机完成；AI 生成会调用当前配置的模型（出网提示见界面）。
 */
import { useCallback, useState } from 'react'
import { apiAskWechat, apiGetSessions } from '../api.ts'
import type { AskResult, WechatSession } from '@deepseek-ai/dsh-wechat-data/types'
import { Badge, Card, PanelHeader, Select } from '../ui/kit.tsx'
import css from './ask.module.css'

const EXAMPLES = [
  '上周三我和李四聊了什么？',
  '谁答应过我下周交报告？',
  '最近一次转账给我的是谁？',
]

/**
 * Render the WeChat Q&A panel.
 * @param props - optional chat navigation callback.
 * @returns the ask panel element tree.
 */
export function AskPanel({ onOpenChat }: { onOpenChat?: (username: string, localId?: number) => void } = {}): React.JSX.Element {
  const [sessions, setSessions] = useState<readonly WechatSession[]>([])
  const [scopeUsername, setScopeUsername] = useState('')
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [question, setQuestion] = useState('')
  const [result, setResult] = useState<AskResult | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [asking, setAsking] = useState(false)

  const loadSessions = useCallback(async (): Promise<void> => {
    try {
      const env = await apiGetSessions({ limit: 500 })
      setSessions(env.sessions)
    } catch {
      /* 会话列表加载失败不阻塞提问 */
    }
  }, [])

  // 会话选项在用户实际打开范围选择器时再加载，不在进入页签时拉全量会话。
  // （Remote 侧带 30s 快照缓存，重复聚焦不会重复请求。）

  const ask = useCallback(async (): Promise<void> => {
    const q = question.trim()
    if (!q || asking) return
    setAsking(true)
    setError(null)
    try {
      const r = await apiAskWechat({
        question: q,
        ...(scopeUsername ? { username: scopeUsername } : {}),
        ...(from ? { from } : {}),
        ...(to ? { to } : {}),
      })
      setResult(r)
    } catch (e) {
      setError((e as Error).message)
    } finally {
      setAsking(false)
    }
  }, [question, asking, scopeUsername, from, to])

  return (
    <div className={css.panel}>
      <PanelHeader
        title="微信问答"
        desc="基于本机微信聊天记录检索回答 · 引用可点击跳转原文"
        actions={(
          <>
            <Badge tone="cyan">{sessions.length} 可检索会话</Badge>
            {result && <Badge tone="purple">{result.citations.length} 引用来源</Badge>}
            {result && <Badge tone="green">{result.answer.length} 回答字符</Badge>}
          </>
        )}
      />

      <Card title="提问">
        <div className={css.row}>
          <label className={css.fieldLabel} htmlFor="ask-scope">会话范围</label>
          <Select
            value={scopeUsername}
            onChange={(v) => { setScopeUsername(v) }}
            options={[{ value: '', label: '全部会话' }, ...sessions.map(s => ({ value: s.username, label: s.displayName || s.username }))]}
            onOpen={() => { void loadSessions() }}
            ariaLabel="会话范围"
          />
          <label className={css.fieldLabel} htmlFor="ask-from">从</label>
          <input id="ask-from" className={css.input} type="date" value={from} onChange={(e) => { setFrom(e.target.value) }} />
          <label className={css.fieldLabel} htmlFor="ask-to">到</label>
          <input id="ask-to" className={css.input} type="date" value={to} onChange={(e) => { setTo(e.target.value) }} />
        </div>
        <textarea
          className={css.textarea}
          value={question}
          onChange={(e) => { setQuestion(e.target.value) }}
          placeholder="例如：上周我和张三聊了什么？"
          rows={4}
          aria-label="微信问答问题"
        />
        <div className={css.actions}>
          <button type="button" className={css.askBtn} onClick={() => { void ask() }} disabled={!question.trim() || asking}>
            {asking ? '检索与生成中…' : '提问'}
          </button>
          {(question.trim() || result || error) && (
            <button type="button" className={css.clearBtn} onClick={() => { setQuestion(''); setResult(null); setError(null) }}>
              清空
            </button>
          )}
          <span className={css.egress}>🔒 检索在本机完成；AI 生成会把检索片段发送到所选模型（可在「隐私与信任」中关闭出网）</span>
        </div>
      </Card>

      {error && <div className={css.error} role="alert">{error}</div>}

      {asking && <div className={css.loading}>正在检索本机聊天记录并生成回答…</div>}

      {result && !asking && (
        <Card title="回答">
          <div className={css.answer}>{result.answer}</div>
          {result.citations.length > 0 && (
            <>
              <div className={css.citesTitle}>来源（点击跳转原文）</div>
              <div className={css.cites}>
                {result.citations.map((c, i) => (
                  <button
                    key={`${c.username}:${c.local_id}:${i}`}
                    type="button"
                    className={css.citeBtn}
                    onClick={() => { onOpenChat?.(c.username, c.local_id) }}
                    title={`${c.name} · ${c.time} · ${c.snippet}`}
                  >
                    <span className={css.citeIdx}>[{i + 1}]</span>
                    <span className={css.citeName}>{c.name}</span>
                    <span className={css.citeTime}>{c.time}</span>
                    <span className={css.citeSnippet}>{c.snippet}</span>
                  </button>
                ))}
              </div>
            </>
          )}
        </Card>
      )}

      {!result && !asking && !error && (
        <div className={css.tip}>
          <div className={css.tipTitle}>可以这样问（点击示例直接填充）</div>
          <div className={css.exampleGrid}>
            {EXAMPLES.map(ex => (
              <button key={ex} type="button" className={css.exampleBtn} onClick={() => { setQuestion(ex); setResult(null); setError(null) }}>
                {ex}
              </button>
            ))}
          </div>
          <p className={css.tipText}>回答会附上可跳转的本机聊天来源；检索在本机完成，仅把检索片段发送到所选模型。</p>
        </div>
      )}
    </div>
  )
}
